awk 'BEGIN{g=""};/Thermal correction to Gibbs Free Energy/ {for(i=1;i<=NF;i++){if($i ~ /^[-+]?[0-9]*\.?[0-9]+([eE][-+]?[0-9]+)?$/){g=$i;break}}; if(g=="" && match($0,/Thermal correction to Gibbs Free Energy[[:space:]]*=[[:space:]]*([+-]?[0-9]*\.?[0-9]+([eE][+-]?[0-9]+)?)/,m)){g=m[1]}; if(g!=""){print g; exit}};/Gibbs free energy/ {for(i=1;i<=NF;i++){if($i ~ /^[-+]?[0-9]*\.?[0-9]+([eE][-+]?[0-9]+)?$/){g=$i;break}}; if(g=="" && match($0,/Gibbs free energy[[:space:]]*[:=][[:space:]]*([+-]?[0-9]*\.?[0-9]+([eE][+-]?[0-9]+)?)/,m)){g=m[1]}; if(g!=""){print g; exit}};END{if(g!="") print g}' $1
